console.log("Привет!!!");console.log("Привет!");document.addEventListener("DOMContentLoaded",(function(){var progressSpans=document.querySelectorAll(".progress-bar");progressSpans.forEach((function(span){var progress=span.getAttribute("data-progress");span.style.width=progress+"%";var progressText=document.createElement("div");progressText.className="progress__number";progressText.textContent=progress+"%";var parent=span.parentElement;parent.appendChild(progressText)}))}));